import json
import os
import sys
import time
from typing import Any, Callable, Dict, Optional

from google.cloud import pubsub_v1

PROJECT_ID = os.environ.get("GCP_PROJECT_ID") or os.environ.get("GOOGLE_CLOUD_PROJECT")
SOURCE_TOPIC = os.environ.get("PUBSUB_SOURCE_TOPIC")
DEAD_LETTER_TOPIC = os.environ.get("PUBSUB_DEAD_LETTER_TOPIC")
MAX_RETRIES = int(os.environ.get("PUBSUB_MAX_RETRIES", "3"))


def _get_publisher() -> pubsub_v1.PublisherClient:
    return pubsub_v1.PublisherClient()


def _topic_path(client: pubsub_v1.PublisherClient, project_id: str, topic_name: str) -> str:
    return client.topic_path(project_id, topic_name)


def send_to_dead_letter(message: Dict[str, Any], error: str, retry_count: int) -> str:
    if not PROJECT_ID:
        raise ValueError("Missing GCP_PROJECT_ID or GOOGLE_CLOUD_PROJECT environment variable")
    if not DEAD_LETTER_TOPIC:
        raise ValueError("Missing PUBSUB_DEAD_LETTER_TOPIC environment variable")

    publisher = _get_publisher()
    dead_letter_path = _topic_path(publisher, PROJECT_ID, DEAD_LETTER_TOPIC)

    payload = {
        "original_message": message,
        "error": error,
        "retry_count": retry_count,
        "failed_at_unix_ms": int(time.time() * 1000),
    }
    data = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    future = publisher.publish(
        dead_letter_path,
        data,
        content_type="application/json",
        source_topic=SOURCE_TOPIC or "",
        dead_letter="true",
        retry_count=str(retry_count),
    )
    return future.result(timeout=30)


def process_with_dead_letter(
    message: Dict[str, Any],
    handler: Callable[[Dict[str, Any]], Any],
    retry_count: int = 0,
) -> Optional[Any]:
    try:
        return handler(message)
    except Exception as exc:
        if retry_count >= MAX_RETRIES:
            send_to_dead_letter(message, str(exc), retry_count)
            return None
        raise


def _demo_handler(message: Dict[str, Any]) -> str:
    if message.get("should_fail"):
        raise RuntimeError("Simulated processing failure")
    return "ok"


def main() -> None:
    if len(sys.argv) < 2:
        raise SystemExit("Usage: python script.py '<json-message>'")

    message = json.loads(sys.argv[1])
    try:
        result = process_with_dead_letter(message, _demo_handler, retry_count=int(message.get("retry_count", 0)))
        if result is not None:
            print(result)
    except Exception as exc:
        print(f"Processing failed and will be retried: {exc}", file=sys.stderr)
        raise


if __name__ == "__main__":
    main()
